/**
 * The corpus location registry. Committed source of truth (data/ is gitignored); the corpus
 * database mirrors it into a `locations` table at collect time so ad-hoc SQL can join on
 * location_id. Two halves: the hand-written entries below, and the stratified global sample
 * (sampled-locations.json, generated by sample-locations.ts) appended at load time. The
 * collector picks new entries up on the next run.
 */
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { windowIso } from "./lattice.ts";

// Which slice of the corpus a location belongs to. `favorites` = the original Windy-favorites
// import (ski-skewed — the reason the corpus was expanded), validation-only (split: eval) —
// codebooks train exclusively on the sampled strata: `koppen` (land, stratified by Köppen–Geiger
// subtype) and `ocean` (30° latitude bands).
export type Stratum = "favorites" | "koppen" | "ocean";

export interface Location {
  id: string;
  name: string;
  lat: number;
  lon: number;
  elev_m?: number;   // pin model elevation (curated peaks); omit for generic grid points
  stratum: Stratum;
  koppen?: string;   // Köppen–Geiger subtype (e.g. Cfb) or "ocean", filled by the sampler
  split?: "train" | "eval"; // held-out split, assigned per location (never per window)
  windows?: string[]; // lattice window starts to collect; absent = every lattice window
}

type Entry = Omit<Location, "stratum">;

