// The committed output of sample-locations.ts: 10k sites stratified by Köppen subtype (√area
// allocation) + ocean latitude bands, each with 12 committed lattice-window picks. Kept as
// compact JSON (subtype, 3-dp coords, window indices); everything displayable is derived here.
interface SampledSite {
  id: string;
  k: string; // Köppen subtype, or "ocean"
  lat: number;
  lon: number;
  split: "train" | "eval";
  wi: number[]; // lattice window indices (see lattice.ts windowIso)
}

const fmtCoord = (lat: number, lon: number): string =>
  `${Math.abs(lat).toFixed(2)}°${lat < 0 ? "S" : "N"} ${Math.abs(lon).toFixed(2)}°${lon < 0 ? "W" : "E"}`;

const SAMPLED_PATH = join(dirname(fileURLToPath(import.meta.url)), "sampled-locations.json");
const SAMPLED: Location[] = existsSync(SAMPLED_PATH)
  ? (JSON.parse(readFileSync(SAMPLED_PATH, "utf8")).sites as SampledSite[]).map((s) => ({
      id: s.id,
      name: `${s.k === "ocean" ? "Ocean" : s.k} ${fmtCoord(s.lat, s.lon)}`,
      lat: s.lat,
      lon: s.lon,
      stratum: s.k === "ocean" ? "ocean" : "koppen",
      koppen: s.k,
      split: s.split,
      windows: s.wi.map(windowIso),
    }))
  : [];

export const LOCATIONS: Location[] = [
  ...FAVORITES.map((l): Location => ({ ...l, stratum: "favorites", split: "eval" })),
  ...SAMPLED,
];
